[
  {
    "name": "real_data_dif_mmlu",
    "description": "METABENCH MMLU 5,219×12,508 response matrix 上的 MH-DIF，temporal/ability/within-family cohort 对比 + Li et al. proxy validation + domain-specificity。\n",
    "results": {
      "temporal_ets_c_pct": 31.3,
      "temporal_fpr_li_clean": 0.321,
      "temporal_enrichment": 0.96,
      "ability_ets_c_pct": 2.9,
